CREATE TABLE public.store_catalog (id text PRIMARY KEY, name text NOT NULL, city text NOT NULL DEFAULT '');
GRANT SELECT ON public.store_catalog TO authenticated; GRANT ALL ON public.store_catalog TO service_role;
ALTER TABLE public.store_catalog ENABLE ROW LEVEL SECURITY;
INSERT INTO public.store_catalog SELECT id,name,city FROM public.store_records WHERE id IN ('L001','L002','L003','L004','L005','L006','L007','L008','L009','L010','L011','L012');
CREATE TABLE public.store_identity_migration_backup (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_table text NOT NULL, original_id text NOT NULL, row_data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(source_table,original_id));
GRANT ALL ON public.store_identity_migration_backup TO service_role;
ALTER TABLE public.store_identity_migration_backup ENABLE ROW LEVEL SECURITY;
CREATE TYPE public.app_role AS ENUM ('admin','member');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_roles ON public.user_roles FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE TABLE public.workspace_members (user_id uuid PRIMARY KEY, workspace_id text NOT NULL DEFAULT 'farmasull', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.workspace_members TO authenticated; GRANT ALL ON public.workspace_members TO service_role;
ALTER TABLE public.workspace_members ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_membership ON public.workspace_members FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE FUNCTION public.is_fapp_member() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.workspace_members WHERE user_id=auth.uid() AND workspace_id='farmasull') $$;
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.is_fapp_member() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.is_fapp_member() TO authenticated;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated;
CREATE POLICY catalog_members ON public.store_catalog FOR SELECT TO authenticated USING (public.is_fapp_member());
CREATE TABLE public.workspace_invitations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email text NOT NULL,role public.app_role NOT NULL DEFAULT 'member',expires_at timestamptz NOT NULL DEFAULT (now()+interval '7 days'),accepted_by uuid,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.workspace_invitations TO authenticated; GRANT ALL ON public.workspace_invitations TO service_role;
ALTER TABLE public.workspace_invitations ENABLE ROW LEVEL SECURITY;
CREATE POLICY invitations_admin ON public.workspace_invitations TO authenticated USING (public.has_role(auth.uid(),'admin') AND public.is_fapp_member()) WITH CHECK (public.has_role(auth.uid(),'admin') AND public.is_fapp_member());
CREATE FUNCTION public.accept_fapp_invitation() RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_id uuid; v_role public.app_role; v_email text; BEGIN SELECT email INTO v_email FROM auth.users WHERE id=auth.uid() AND email_confirmed_at IS NOT NULL; IF v_email IS NULL THEN RETURN false; END IF; SELECT id,role INTO v_id,v_role FROM public.workspace_invitations WHERE lower(email)=lower(v_email) AND accepted_by IS NULL AND expires_at>now() ORDER BY created_at DESC LIMIT 1 FOR UPDATE; IF v_id IS NULL THEN RETURN false; END IF; INSERT INTO public.workspace_members(user_id) VALUES(auth.uid()) ON CONFLICT DO NOTHING; INSERT INTO public.user_roles(user_id,role) VALUES(auth.uid(),v_role) ON CONFLICT DO NOTHING; UPDATE public.workspace_invitations SET accepted_by=auth.uid() WHERE id=v_id; RETURN true; END $$;
REVOKE ALL ON FUNCTION public.accept_fapp_invitation() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.accept_fapp_invitation() TO authenticated;
CREATE TABLE public.fapp_monthly_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id text NOT NULL DEFAULT 'farmasull',store_id text NOT NULL REFERENCES public.store_catalog(id),reference_month text NOT NULL,payload jsonb NOT NULL DEFAULT '{}',updated_by uuid NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,store_id,reference_month));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.fapp_monthly_records TO authenticated; GRANT ALL ON public.fapp_monthly_records TO service_role;
ALTER TABLE public.fapp_monthly_records ENABLE ROW LEVEL SECURITY;
CREATE POLICY monthly_team ON public.fapp_monthly_records TO authenticated USING (workspace_id='farmasull' AND public.is_fapp_member()) WITH CHECK(workspace_id='farmasull' AND public.is_fapp_member() AND updated_by=auth.uid());
CREATE TABLE public.fapp_payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),record_id uuid NOT NULL REFERENCES public.fapp_monthly_records(id) ON DELETE CASCADE,payload jsonb NOT NULL);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.fapp_payments TO authenticated; GRANT ALL ON public.fapp_payments TO service_role;
ALTER TABLE public.fapp_payments ENABLE ROW LEVEL SECURITY;
CREATE POLICY payments_team ON public.fapp_payments TO authenticated USING (public.is_fapp_member()) WITH CHECK(public.is_fapp_member());
CREATE TABLE public.fapp_campaigns (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),record_id uuid NOT NULL REFERENCES public.fapp_monthly_records(id) ON DELETE CASCADE,payload jsonb NOT NULL);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.fapp_campaigns TO authenticated; GRANT ALL ON public.fapp_campaigns TO service_role;
ALTER TABLE public.fapp_campaigns ENABLE ROW LEVEL SECURITY;
CREATE POLICY campaigns_team ON public.fapp_campaigns TO authenticated USING (public.is_fapp_member()) WITH CHECK(public.is_fapp_member());
CREATE TABLE public.fapp_products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),record_id uuid NOT NULL REFERENCES public.fapp_monthly_records(id) ON DELETE CASCADE,payload jsonb NOT NULL);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.fapp_products TO authenticated; GRANT ALL ON public.fapp_products TO service_role;
ALTER TABLE public.fapp_products ENABLE ROW LEVEL SECURITY;
CREATE POLICY products_team ON public.fapp_products TO authenticated USING (public.is_fapp_member()) WITH CHECK(public.is_fapp_member());
CREATE FUNCTION public.save_fapp_record(p_payload jsonb,p_confirmed boolean DEFAULT false) RETURNS uuid LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE v_id uuid; BEGIN IF NOT public.is_fapp_member() THEN RAISE EXCEPTION 'Acesso restrito à equipe autorizada'; END IF; IF jsonb_array_length(p_payload->'products')>10 THEN RAISE EXCEPTION 'Máximo de 10 produtos'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended((p_payload->>'storeId')||'::'||(p_payload->>'referenceMonth'),0)); SELECT id INTO v_id FROM public.fapp_monthly_records WHERE workspace_id='farmasull' AND store_id=p_payload->>'storeId' AND reference_month=p_payload->>'referenceMonth'; IF v_id IS NOT NULL AND NOT p_confirmed THEN RAISE EXCEPTION 'Confirme a atualização desta competência'; END IF; INSERT INTO public.fapp_monthly_records(store_id,reference_month,payload,updated_by) VALUES(p_payload->>'storeId',p_payload->>'referenceMonth',p_payload,auth.uid()) ON CONFLICT(workspace_id,store_id,reference_month) DO UPDATE SET payload=excluded.payload,updated_by=auth.uid(),updated_at=now() RETURNING id INTO v_id; DELETE FROM public.fapp_payments WHERE record_id=v_id; DELETE FROM public.fapp_campaigns WHERE record_id=v_id; DELETE FROM public.fapp_products WHERE record_id=v_id; INSERT INTO public.fapp_payments(record_id,payload) SELECT v_id,value FROM jsonb_array_elements(p_payload->'payments'); INSERT INTO public.fapp_campaigns(record_id,payload) SELECT v_id,value FROM jsonb_array_elements(p_payload->'campaigns'); INSERT INTO public.fapp_products(record_id,payload) SELECT v_id,value FROM jsonb_array_elements(p_payload->'products'); RETURN v_id; END $$;
REVOKE ALL ON FUNCTION public.save_fapp_record(jsonb,boolean) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.save_fapp_record(jsonb,boolean) TO authenticated;